// Package indexroom implements chain ingestion with optional block
// timestamps, reorg handling, consistent paginated transaction queries, and
// time-bucketed transaction statistics over the main chain.
package indexroom

import (
	"fmt"
	"sync"
	"unicode/utf8"
)

// Block is one ingested block with its transactions.
//
// Time is the optional block timestamp as non-negative Unix seconds. A nil
// pointer means the block carries no timestamp and is distinct from a
// timestamp of zero. Append and Reorg reject negative values; stored blocks
// keep their own copy, so mutating the pointer or its target after a call
// never affects the index. Block timestamps need not be monotonic: equal
// values and values that decrease with height are both accepted.
type Block struct {
	Height int64
	// Hash, Parent, and every Txs identifier must be valid UTF-8; Append and
	// Reorg reject a block carrying invalid bytes rather than letting a
	// snapshot export silently rewrite them to U+FFFD. Txs keeps empty and
	// duplicated identifiers, order, case, and surrounding whitespace
	// exactly as given.
	Hash   string
	Parent string
	Txs    []string
	Time   *int64
}

// Index is the durable chain view.
//
// Append, Reorg, QueryTxs, QueryTimeStats, Export, and Restore are safe for
// concurrent use; the exported fields are meant for read-only inspection
// after all calls have finished.
type Index struct {
	Blocks map[int64]Block
	ByHash map[string]int64
	Tip    int64

	mu  sync.Mutex
	key [32]byte
}

// New returns an empty index.
func New() *Index {
	return &Index{Blocks: map[int64]Block{}, ByHash: map[string]int64{}, key: newKey()}
}

// reorgAppliedHookLocked is a test-only rendezvous invoked from Reorg once
// the alternate branch has fully replaced the old tip range, while index.mu
// is still held and before the call returns. It is nil in production; reorg
// regression tests park a successful reorg here with the new chain already in
// effect, so a QueryTimeStats issued at that instant is forced to wait and,
// once it runs, must observe the complete new chain.
var reorgAppliedHookLocked func(newTip int64)

// appendStoredHookLocked is a test-only rendezvous invoked from appendLocked
// right after an Append has fully recorded its accepted block — the block is
// in Blocks and ByHash and Tip has advanced — while index.mu is still held
// and before the call returns. It fires for the Append path only, never for
// stores performed inside Reorg. It is nil in production; Append/Reorg
// interleaving tests park a successful append here so the block is committed
// but the call has not returned, forcing a concurrent Reorg to acquire the
// lock against exactly that intermediate state instead of relying on
// scheduling luck.
var appendStoredHookLocked func(height int64)

// Append accepts a block only when it extends the current tip, keeping the
// chain linear. Re-submitting a block identical to one already on the main
// chain is a successful no-op. A block whose hash, parent, or any transaction
// identifier carries invalid UTF-8 is rejected with an error naming the
// height and field (and the zero-based tx position); a rejected append leaves
// the index untouched.
func (index *Index) Append(block Block) error {
	index.mu.Lock()
	defer index.mu.Unlock()
	return index.appendLocked(block)
}

func (index *Index) appendLocked(block Block) error {
	if err := validateBlockEncoding(block); err != nil {
		return err
	}
	if block.Hash == "" {
		return errInvalid("block needs a hash")
	}
	if block.Time != nil && *block.Time < 0 {
		return errInvalid("block time must not be negative")
	}
	if index.Tip == 0 {
		// Empty index: only the first block at height 1 is accepted; its
		// parent becomes the chain start identifier and need not be indexed.
		if block.Height != 1 {
			return errInvalid("first block must be at height 1")
		}
		index.storeLocked(block)
		if appendStoredHookLocked != nil {
			appendStoredHookLocked(block.Height)
		}
		return nil
	}
	if old, exists := index.Blocks[block.Height]; exists {
		if sameBlock(old, block) {
			return nil
		}
		return errInvalid("height already indexed with different content")
	}
	if block.Height != index.Tip+1 {
		return errInvalid("block height must extend the current tip")
	}
	if block.Parent != index.Blocks[index.Tip].Hash {
		return errInvalid("parent does not match the current tip")
	}
	if _, exists := index.ByHash[block.Hash]; exists {
		return errInvalid("hash already indexed at another height")
	}
	index.storeLocked(block)
	if appendStoredHookLocked != nil {
		appendStoredHookLocked(block.Height)
	}
	return nil
}

// Reorg replaces the tip range with an alternate branch and reports the
// dropped old heights in ascending order. The branch is validated in full
// before anything is applied — including UTF-8 validity of every block's
// hash, parent, and transaction identifiers, even in the last block — so a
// rejected reorg leaves the index exactly as it was and reports no dropped
// heights. Heights whose old block is identical to the new one are not
// reported; re-submitting the branch already in effect returns an empty list.
func (index *Index) Reorg(blocks []Block) ([]int64, error) {
	index.mu.Lock()
	defer index.mu.Unlock()

	if len(blocks) == 0 {
		return nil, errInvalid("empty branch")
	}
	// Every identifier must be valid UTF-8 before any lookup or mutation.
	// The first block's parent need not be indexed, but it still has to be
	// encodable, and an error in the last block must reject the whole branch.
	for _, block := range blocks {
		if err := validateBlockEncoding(block); err != nil {
			return nil, err
		}
	}
	ancestor, ok := index.ByHash[blocks[0].Parent]
	if !ok {
		return nil, errInvalid("branch parent is unknown")
	}
	if blocks[0].Height != ancestor+1 {
		return nil, errInvalid("branch must start at the ancestor height plus one")
	}
	seen := make(map[string]bool, len(blocks))
	for i, block := range blocks {
		if block.Hash == "" {
			return nil, errInvalid("block needs a hash")
		}
		if block.Time != nil && *block.Time < 0 {
			return nil, errInvalid("block time must not be negative")
		}
		if seen[block.Hash] {
			return nil, errInvalid("duplicate hash inside branch")
		}
		seen[block.Hash] = true
		if height, exists := index.ByHash[block.Hash]; exists && height <= ancestor {
			return nil, errInvalid("hash conflicts with a retained block")
		}
		if i > 0 {
			prev := blocks[i-1]
			if block.Height != prev.Height+1 {
				return nil, errInvalid("branch heights must be consecutive")
			}
			if block.Parent != prev.Hash {
				return nil, errInvalid("branch parent does not match the previous block")
			}
		}
	}

	// Everything validated; compute the dropped heights before mutating.
	newTip := blocks[len(blocks)-1].Height
	dropped := []int64{}
	for height := ancestor + 1; height <= index.Tip; height++ {
		if height > newTip {
			dropped = append(dropped, height)
			continue
		}
		if !sameBlock(index.Blocks[height], blocks[height-blocks[0].Height]) {
			dropped = append(dropped, height)
		}
	}
	for height := ancestor + 1; height <= index.Tip; height++ {
		delete(index.ByHash, index.Blocks[height].Hash)
		delete(index.Blocks, height)
	}
	index.Tip = ancestor
	for _, block := range blocks {
		index.storeLocked(block)
	}
	if reorgAppliedHookLocked != nil {
		reorgAppliedHookLocked(index.Tip)
	}
	return dropped, nil
}

// storeLocked records a validated block, copying its transactions and
// timestamp so later caller-side mutation cannot alter the stored block.
func (index *Index) storeLocked(block Block) {
	if block.Txs != nil {
		txs := make([]string, len(block.Txs))
		copy(txs, block.Txs)
		block.Txs = txs
	}
	if block.Time != nil {
		t := *block.Time
		block.Time = &t
	}
	index.Blocks[block.Height] = block
	index.ByHash[block.Hash] = block.Height
	index.Tip = block.Height
}

// validateBlockEncoding rejects a block whose hash, parent, or any
// transaction identifier contains invalid UTF-8 bytes. JSON snapshots can
// only carry valid UTF-8 — the encoder would silently rewrite bad bytes to
// U+FFFD, merging distinct identifiers after a restore — so such a block can
// never enter the index. The error names the block height and the field; a
// bad transaction identifier also names its zero-based position. A genuine
// U+FFFD is valid UTF-8 and is never rejected by this check.
func validateBlockEncoding(block Block) error {
	if !utf8.ValidString(block.Hash) {
		return errInvalid(fmt.Sprintf("block at height %d: field %q contains invalid UTF-8 bytes", block.Height, "hash"))
	}
	if !utf8.ValidString(block.Parent) {
		return errInvalid(fmt.Sprintf("block at height %d: field %q contains invalid UTF-8 bytes", block.Height, "parent"))
	}
	for position, tx := range block.Txs {
		if !utf8.ValidString(tx) {
			return errInvalid(fmt.Sprintf("block at height %d: field %q element %d contains invalid UTF-8 bytes", block.Height, "txs", position))
		}
	}
	return nil
}

// sameBlock reports whether two blocks are identical: same height, hash,
// parent, transactions in order, and timestamp presence and value. An empty
// tx list equals a missing one, but a missing timestamp never equals zero.
func sameBlock(a, b Block) bool {
	if a.Height != b.Height || a.Hash != b.Hash || a.Parent != b.Parent {
		return false
	}
	if len(a.Txs) != len(b.Txs) {
		return false
	}
	for i := range a.Txs {
		if a.Txs[i] != b.Txs[i] {
			return false
		}
	}
	if (a.Time == nil) != (b.Time == nil) {
		return false
	}
	return a.Time == nil || *a.Time == *b.Time
}

type errInvalid string

func (e errInvalid) Error() string { return string(e) }

# 链上索引与交易分析服务

## 用途

区块与交易摄取（含可选区块时间）、事件解码与规范化、可组合查询与按时间窗口分段的交易聚合、索引重建与一致性校验、分析指标与快照。

本仓库是可持续演进的自托管 Go 应用。领域核心位于 `indexroom/`，命令入口位于 `cmd/indexroom/`。

```bash
go run ./cmd/indexroom demo
go run ./cmd/indexroom version
go test ./...
```

## 主要接口

- `indexroom.Block` 的 `Time *int64` 字段携带非负 Unix 秒数；`nil` 表示未提供时间，与时间为 0 严格区分。
- `Index.Append` / `Index.Reorg`：摄取区块与重组，负时间整体拒绝且不改变已有链；哈希、父哈希或任一交易标识含非法 UTF-8 字节时同样整体拒绝，错误信息指出区块高度与字段（交易标识另指出从 0 开始的位置），保证快照可无损导出与恢复。`Append` 在链顶前进后仍可再次提交内容完全相同的旧区块（成功且无副作用），完整规则见下方[重复提交区块指南（Append）](#重复提交区块指南append)；`Reorg` 的分支范围、丢弃高度口径、失败原子性与完整用法见下方[重组指南（Reorg）](#重组指南reorg)。
- `Index.QueryTxs`：既有分页交易查询，围绕一个或多个交易标识读取主链上的每次出现；默认按高度、再按块内位置升序返回，`Order` 设为 `OrderDesc` 时整体倒序（高度与块内位置均从大到小）；`TimeStart`/`TimeEnd` 可同时给出非负 Unix 秒，叠加 `[Start, End)` 半开时间窗口筛选（含起点、排除终点，与 `QueryTimeStats` 一致；缺失区块时间不命中，真实零秒按窗口判断），两者都不传表示不启用时间筛选；`MinBlocks` 为正数时只保留至少出现在该数量个**不同区块**中的交易标识（零值不筛选，按第一页固定的完整范围判定）；固定高度范围内的区块时间变化会使旧游标返回 `ErrQueryChanged`。完整翻页用法见下方[分页交易查询指南](#分页交易查询指南querytxs)。
- `Index.QueryTimeStats`：按 `[Start, End)` 半开窗口与 `StepSeconds` 分段统计交易出现次数、不同标识数、含匹配交易的区块数，并给出整窗口去重汇总与缺失时间区块数；非法参数返回 `ErrInvalidArgument`。完整用法见下方[按时间窗口统计交易指南](#按时间窗口统计交易指南querytimestats)。
- `Index.Export` / `Index.Restore`：快照版本 1（区块不含 `timestamp`）与版本 2（任一块有时间时为每块输出必填 `timestamp`，缺失为 `null`）。`Restore` 保证**数据一致**并把再导出规范化为本功能的固定文本，不保留输入的字段顺序、空白与转义写法；它用一份完整快照整体替换主链，非法输入返回 `ErrInvalidSnapshot` 且不改变现有链；底层读取失败（包括与完整快照字节一起送达的故障）不是 `ErrInvalidSnapshot`，而是包装为 `indexroom: read snapshot: ...` 并保留原始读取错误，同样不改变现有链。完整用法见下方[快照导出与恢复指南（Export/Restore）](#快照导出与恢复指南exportrestore)。

## 分页交易查询指南（QueryTxs）

`Index.QueryTxs(query TxQuery) (TxPage, error)` 围绕一个或多个交易标识读取这些标识在主链上的**每一次出现**。默认按"高度、再按块内位置"升序；`Order` 设为 `OrderDesc` 时在整个固定范围内倒序——高度从大到小，同一区块内的位置也从大到小。次序只由高度与原有块内位置决定，区块时间是否缺失、相同或随高度下降都不影响次序。查询只读，可与摄取并发调用，每次调用都看到一个完整的链状态。

- `TxQuery`：`From`/`To` 为闭区间高度，`TxIDs` 为筛选标识集合，`PageSize` 为每页条数（0 取 `DefaultPageSize=100`，最大 `MaxPageSize=1000`），`Order` 为读取方向（零值 `OrderAsc` 升序，`OrderDesc` 倒序），`TimeStart`/`TimeEnd` 为可选时间窗口（两个 `*int64`，同时给出才启用，半开 `[Start, End)`，单位为非负 Unix 秒），`MinBlocks` 为可选的最少区块数门槛（零值不筛选；正数要求标识至少出现在该数量个不同区块，详见下方[最少区块数门槛](#最少区块数门槛minblocks)），`Cursor` 为续查游标。
- `TxHit`：一次命中，字段为 `Height`、`BlockHash`、`TxID`、`Position`（块内从 0 开始的位置；**倒序不会重新编号**）。
- `TxPage`：本页 `Hits`，以及对整个固定范围的统计 `TotalMatches`（匹配出现总次数）、`MatchedBlocks`（含匹配交易的区块数）、`ToHeight`（第一页固定下来的实际上界）和 `NextCursor`。统计是整个固定范围的统计，**不随方向或页大小改变**。

### 如何取得第一页、继续读取、何时结束

1. **第一页**：`Cursor` 传空字符串即首次查询。`From` 为 0 时默认从高度 1 开始；`To` 为 0 时取首次查询看到的链顶。需要先看靠近链顶的记录时，把 `Order` 设为 `OrderDesc`（见下方[倒序读取](#倒序读取orderdesc)）。
2. **继续读取**：把上一页返回的 `NextCursor` 原样填回 `TxQuery.Cursor` 再次调用。游标是服务返回的**不透明字符串**，不要解析或拼接。续查时高度范围、`TxIDs`、读取方向 `Order`、是否启用时间窗口和窗口本身、以及 `MinBlocks` 门槛必须与第一页等价或一致；`PageSize` 可以逐页调整。
3. **结束**：返回页的 `NextCursor` 为空即最后一页。范围内没有匹配交易时不是错误，而是成功返回一个空页（`Hits` 为空、无游标）。

重复出现的交易**不会合并**：同一标识在不同区块、或同一区块内出现多次，就返回多条 `TxHit`。筛选按字符串精确匹配，`TxIDs` 的**顺序与重复项不影响匹配**（`["a","a"]` 与 `["a"]` 等价）；但大小写与首尾空白仍按原字符串区分（`"A"`、`" a "` 都不会匹配 `"a"`）。

### 范围在第一页固定

- 第一页若显式给出高于当前链顶的 `To`，返回的 `ToHeight` 是夹到链顶后的值；**后续请求仍要传原先请求的 `To`，不能用返回值替换**（例如首查 `To=10`、链顶只有 3 时 `ToHeight=3`，续查仍须传 `To=10`）。
- 范围固定后，之后新追加的区块对本次翻页不可见：第一页之后再追加含匹配标识的区块，继续翻页仍只读取原来固定的范围，`TotalMatches`、`MatchedBlocks` 也不增加。需要新数据就以空游标重新开始一次查询。

### 游标失效：区分 ErrQueryChanged 与 ErrInvalidArgument

- **`ErrQueryChanged`（链数据变了）**：固定范围内任一区块的内容发生改变——即使区块哈希不变、**只改变了时间**——或链顶退到固定结束高度以下，续查都会返回该错误，且**没有可用的页结果**。此时只能**从空游标重新开始第一页**，绝不能把新结果拼接到旧结果后面。
- **`ErrInvalidArgument`（请求本身不合法）**：续查更改高度范围或筛选集合、**续查方向与游标不一致**（正序游标配 `OrderDesc`，或倒序游标配 `OrderAsc`/不传 `Order`）、**续查改变时间筛选的启用状态或窗口任一边界**、**续查改变 `MinBlocks` 门槛（含零与正数之间切换）或传入负门槛**、只给时间窗口一个边界、时间边界为负、起点不小于终点、传入非法 `Order` 值、游标损坏、或把游标交给另一个索引实例（游标带实例签名，跨实例无效）。它与链数据变化无关，用 `errors.Is` 与 `ErrQueryChanged` 区分；请先修正请求再重试。方向、窗口或门槛不一致的续查同样**不返回任何可用页结果**。

### 倒序读取（OrderDesc）

- **选择倒序**：第一页把 `TxQuery.Order` 设为 `indexroom.OrderDesc`。不设置（零值 `OrderAsc`）时行为与过去完全一致，原有正序调用与有效游标都不受影响。
- **整体次序**：倒序作用于**整个固定范围**，不是只翻转当前页。命中按高度从大到小返回，同一区块内的 `Position` 也从大到小；逐页拼接后仍符合这一整体次序。每条命中的 `Position` 仍是它在区块内从 0 开始的真实位置，**不会因为倒序重新编号**；同一标识的每次出现也**不会合并**。
- **继续翻页**：续查必须沿用第一页的读取方向，继续把 `NextCursor` 原样传回；`PageSize` 仍可逐页调整，未读记录既不重复也不遗漏。
- **切换方向**：不能拿一个方向的游标去续查另一个方向——会得到 `ErrInvalidArgument`。要改读另一方向，**以空游标重新发起一次第一页查询**（此时会按当时的链顶重新固定范围）。
- **范围固定与统计**：第一页照旧固定实际上界，随后追加的更高区块不能插进进行中的倒序翻页；要读取这些新记录同样需要空游标重查。`TotalMatches`、`MatchedBlocks`、`ToHeight` 仍是整个固定范围的统计，与方向、页大小无关。
- **空结果**：空链、起始高度超过链顶、或筛选无命中时，倒序也成功返回空页与空的后续游标。

例如高度 1 至 3 的交易依次是 `[a,b,a]`、`[a,c]`、`[b,a]`，筛选 `a`、每页 2 条时：第一页依次给出**高度 3 位置 1、高度 2 位置 0**，第二页依次给出**高度 1 位置 2、高度 1 位置 0**，随后结束翻页；两页的 `TotalMatches` 都是 4、`MatchedBlocks` 都是 3。

### 时间窗口筛选（TimeStart/TimeEnd）

- **启用方式**：`TxQuery.TimeStart` 与 `TxQuery.TimeEnd` 同时给出非 `nil` 的 `*int64`，即按**半开窗口 `[Start, End)`** 筛选区块时间（非负 Unix 秒，**包含起点、排除终点**），语义与 `QueryTimeStats` 一致。两个字段都不传（均为 `nil`）时**不启用**时间筛选，行为与过去完全一致，原有调用与有效游标不受影响。
- **未启用与起点为零是两回事**：调用方必须能区分"没有时间筛选"（两个指针都为 `nil`）与"窗口起点恰好为零"（`TimeStart` 指向 0、`TimeEnd` 指向更大的值）。只给一个边界（只给起点或只给终点）是 `ErrInvalidArgument`。
- **缺失时间不命中，真实零秒按窗口判断**：启用窗口后，`Time` 为 `nil`（没有时间）的区块**永不命中**；时间为 0 是真实时间戳，按数值与窗口比较（例如窗口 `[0,1)` 会保留它）。这与摄取、快照中"缺失时间不是 0"的区分一致。
- **三类条件共同生效**：一次出现必须**同时**落在高度范围、时间窗口内、且标识通过 `TxIDs` 筛选才被保留。时间窗口只决定哪些出现被保留，**不改变读取次序**——结果仍按高度与原有块内位置正序或倒序读取，不能改成按时间排序；同一标识的重复出现既**不合并也不重新编号**，`Position` 仍是块内从 0 开始的真实位置。时间允许随高度下降、允许相等，均按实际值判断。
- **统计口径**：`TotalMatches` 与 `MatchedBlocks` 描述**固定高度范围内通过全部条件**（标识 + 时间窗口）的出现次数与区块数，每页保持一致；`ToHeight` 仍表示第一页固定下来的高度上界，与是否启用窗口无关。合法窗口没有命中时不是错误：成功返回空页（`Hits` 为空、无后续游标）。
- **参数错误**：只提供一个边界、起点或终点为负、起点不小于终点，都返回 `ErrInvalidArgument` 且**不提供可用页**。
- **继续翻页沿用同一窗口**：续查必须沿用"是否启用时间筛选"及完全相同的窗口；在启用与不启用之间切换、或改变任一边界，都返回 `ErrInvalidArgument` 且没有可用页，调用方需**从空游标重新查询**。`PageSize` 仍可逐页调整。
- **范围变化判定不变**：固定范围内**任一**区块内容变化（包括原本因时间不在窗口内而未命中的区块、缺失时间变成已知时间等）续查仍返回 `ErrQueryChanged` 且没有可用页，必须从空游标重新开始，不能把新结果接到旧结果后面。

例如高度一至四的时间依次为 105、缺失、100、110，交易依次为 `[a,b,a]`、`[a]`、`[a]`、`[a]`。筛选 `a` 与窗口 `[100,110)`、正序每页两条时：第一页返回**高度一的位置零和位置二**（时间 105 在窗口内；同一区块两次出现都保留），第二页返回**高度三的位置零**（时间 100 在窗口内）；高度二缺失时间不命中、高度四时间 110 正好等于被排除的终点。总出现次数 `TotalMatches=3`、匹配区块数 `MatchedBlocks=2`，高度上界 `ToHeight` 仍为 4。

### 最少区块数门槛（MinBlocks）

`TxQuery.MinBlocks` 在标识筛选与时间窗口之上再叠一层"跨区块复现"条件：只保留至少出现在足够多**不同区块**里的交易标识。

- **零值不启用，正数是门槛**：`MinBlocks` 为 0 或不设置时，查询行为与过去完全一致，原有调用与有效游标不受影响。正数 `N` 表示同一标识必须出现在**至少 `N` 个不同区块**中才算达标。
- **同一区块多次出现只贡献一个区块**：计数按"区块"去重——一个标识在某区块里无论重复多少次，都只让该区块贡献 1；但**一旦达标，该标识的每一次匹配出现都会保留**（包括同一块内的重复出现），不做合并，每条命中的 `Position` 仍是它原来的块内位置（倒序也不重新编号）。
- **按第一页固定的完整范围判定，不按当前页计数**：是否达标用[第一页固定下来的完整高度范围](#范围在第一页固定)统计，而不是只数当前页或已读过的页；因此无论翻到第几页、`PageSize` 多大、正序还是倒序，每页的 `TotalMatches` 与 `MatchedBlocks` 都相同，描述的是**筛选后的完整范围**。换页大小或正倒序都不会改变这两个统计值。
- **与标识筛选、时间窗口共同生效**：只有**同时**通过 `TxIDs` 标识筛选、落在高度范围、并通过时间窗口的区块与交易才参与计数。启用时间窗口后，**缺失时间的区块与窗口外的区块都不帮助任何标识达标**（其中的出现也不返回）；**没有启用时间窗口时，缺失时间不会仅因没有时间而被排除**，照常参与计数。
- **门槛随第一页钉住**：继续翻页必须沿用同一 `MinBlocks`，改变门槛（包括 0 与正数之间切换）返回 `ErrInvalidArgument` 且没有可用页，要改门槛须[从空游标重新查询](#游标失效区分-errquerychanged-与-errinvalidargument)。第一页之后新追加的更高区块对进行中的翻页不可见，**也不会帮助当前查询中的标识达标**；需要它们参与计数就以空游标重新开始。
- **参数错误与无人达标**：负门槛返回 `ErrInvalidArgument`，没有可用页；合法门槛但没有任何标识达到时**不是错误**，而是成功返回空页（`Hits` 为空、`TotalMatches=0`、`MatchedBlocks=0`、`NextCursor` 为空）。

例如高度一至三的交易依次为 `[m,m,n]`、`[n,p]`、`[m,q]`，门槛为 2：`m` 出现在区块 {一,三}、`n` 出现在 {一,二}，二者达标；`p`、`q` 各只出现在一个区块，不返回。达标后 `m` 的三次出现（高度一位置 0、1 与高度三位置 0）和 `n` 的两次出现（高度一位置 2、高度二位置 0）**全部保留，共五条记录、三个匹配区块**（`TotalMatches=5`、`MatchedBlocks=3`）。若高度范围**只包含前两个区块**，则范围内只有 `n` 跨两个区块出现，**只有 `n` 达标**（两条记录、两个匹配区块），`m` 只剩一个区块不达标。

### MinBlocks 完整示例

下面的程序只使用现有公开功能，在本机离线即可运行，源码位于 [`examples/minblocks/main.go`](examples/minblocks/main.go)：

```bash
go run ./examples/minblocks
```

场景与上文短链一致：高度一至三依次为 `[m,m,n]`、`[n,p]`、`[m,q]`，门槛 2、每页 2 条，分三页返回 `m` 的三次与 `n` 的两次出现，每页都带整范围统计 5/3，最后一页后续游标为空；随后演示倒序与改页大小不改变统计、范围只含前两块时只有 `n` 达标、不设门槛沿用原结果、负门槛与续查改门槛返回 `ErrInvalidArgument`、合法门槛无人达标时返回空页、第一页后追加的高度四不帮助当前查询达标（`p` 仍不返回），以及门槛与 `TxIDs`、时间窗口共同生效时缺失时间区块不参与计数。

```go
// 最少区块数筛选（Index.QueryTxs 的 TxQuery.MinBlocks）完整示例：
// 门槛为零或不传时沿用原查询结果；正数要求同一标识至少出现在第一页固定的
// 完整高度范围内的指定数量个不同区块。同一区块内多次出现只贡献一个区块；
// 一旦达标，该标识的每一次匹配出现都保留，位置仍是原来的块内位置。是否达标
// 按完整固定范围判定而非当前页，TotalMatches/MatchedBlocks 描述筛选后的完整
// 范围，不随页大小或正倒序改变。示例还展示门槛与 TxIDs、时间窗口共同生效、
// 续查必须沿用同一门槛、第一页后新追加的更高区块不帮助当前查询中的标识达标、
// 负门槛与续查改变门槛返回 ErrInvalidArgument、合法门槛无人达标时成功返回空页。
//
// 运行：go run ./examples/minblocks
package main

import (
	"errors"
	"fmt"

	"github.com/gzhysuiioo/indexroom-analytics/indexroom"
)

func mustAppend(index *indexroom.Index, block indexroom.Block) {
	if err := index.Append(block); err != nil {
		panic(err)
	}
}

// unix 返回指向给定 Unix 秒的指针，用于设置区块时间或时间窗口边界。
func unix(sec int64) *int64 { return &sec }

func printPage(title string, page indexroom.TxPage) {
	fmt.Println(title + "：")
	for _, hit := range page.Hits {
		fmt.Printf("  命中 height=%d block=%s tx=%q position=%d\n",
			hit.Height, hit.BlockHash, hit.TxID, hit.Position)
	}
	fmt.Printf("  TotalMatches=%d MatchedBlocks=%d ToHeight=%d 有后续游标=%v\n",
		page.TotalMatches, page.MatchedBlocks, page.ToHeight, page.NextCursor != "")
}

func main() {
	fmt.Println("---- 规格短链：高度 1..3 依次为 [m,m,n]、[n,p]、[m,q]，门槛 2 ----")
	// m 出现在区块 {1,3}、n 出现在 {1,2}，都达到门槛 2；p、q 各只在一个
	// 区块出现，不达标、不返回。m 在高度 1 的块内出现两次，达标后两次都保留。
	index := indexroom.New()
	mustAppend(index, indexroom.Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"m", "m", "n"}})
	mustAppend(index, indexroom.Block{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"n", "p"}})
	mustAppend(index, indexroom.Block{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"m", "q"}})

	// 第一页：MinBlocks=2，每页 2 条，范围显式固定在高度 [1,3]。
	query := indexroom.TxQuery{From: 1, To: 3, MinBlocks: 2, PageSize: 2}
	page1, err := index.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	printPage("门槛 2、每页 2 条：第1页", page1)

	// 继续翻页：游标原样传回，门槛（及其他条件）必须与第一页一致。
	query.Cursor = page1.NextCursor
	page2, err := index.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	printPage("第2页（沿用同一门槛与游标）", page2)

	query.Cursor = page2.NextCursor
	page3, err := index.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	printPage("第3页", page3)
	fmt.Printf("最后一页后续游标为空：%v\n", page3.NextCursor == "")
	fmt.Println("  三次出现的 m（高度1位置0、1，高度3位置0）与两次出现的 n（高度1位置2、高度2位置0）全部保留，共 5 条、3 个匹配区块")
	fmt.Println()

	// 整范围判定与页大小、方向无关：一次取完的倒序查询给出同样的 5 条记录与
	// 5/3 统计；每条 Position 仍是原块内位置，倒序不重新编号。
	desc, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 3, MinBlocks: 2, Order: indexroom.OrderDesc})
	if err != nil {
		panic(err)
	}
	fmt.Print("倒序一次取完：")
	for i, hit := range desc.Hits {
		if i > 0 {
			fmt.Print("；")
		}
		fmt.Printf("高度%d %q 位置%d", hit.Height, hit.TxID, hit.Position)
	}
	fmt.Printf("\n  TotalMatches=%d MatchedBlocks=%d，与正序逐页翻页完全一致\n\n", desc.TotalMatches, desc.MatchedBlocks)

	// 高度范围只包含前两个区块时，m 在范围内只出现在高度 1（一个区块），
	// 不达标；n 在高度 1、2 各出现一次，是唯一达到门槛的标识。
	firstTwo, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 2, MinBlocks: 2})
	if err != nil {
		panic(err)
	}
	printPage("范围只含高度 [1,2]、门槛 2（只有 n 达标）", firstTwo)
	fmt.Println()

	// MinBlocks 为零或不传时不启用筛选，沿用原查询：7 次出现全部返回。
	plain, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 3})
	if err != nil {
		panic(err)
	}
	fmt.Printf("不设门槛（MinBlocks=0）：命中 %d 条，TotalMatches=%d MatchedBlocks=%d\n\n",
		len(plain.Hits), plain.TotalMatches, plain.MatchedBlocks)

	// 负门槛是非法查询参数，没有可用页结果。
	bad, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 3, MinBlocks: -1})
	fmt.Printf("负门槛 -1：ErrInvalidArgument=%v 可用命中数=%d\n",
		errors.Is(err, indexroom.ErrInvalidArgument), len(bad.Hits))

	// 续查改变门槛同样是 ErrInvalidArgument：门槛在第一页钉住，要改只能
	// 从空游标重新查询。
	first, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 3, MinBlocks: 2, PageSize: 2})
	if err != nil {
		panic(err)
	}
	changed, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 3, MinBlocks: 1, PageSize: 2, Cursor: first.NextCursor})
	fmt.Printf("续查把门槛从 2 改成 1：ErrInvalidArgument=%v 可用命中数=%d\n",
		errors.Is(err, indexroom.ErrInvalidArgument), len(changed.Hits))

	// 合法门槛但没有任何标识达到：成功的空页，零统计、空游标。
	none, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 3, MinBlocks: 4})
	if err != nil {
		panic(err)
	}
	fmt.Printf("门槛 4（无人达到）：err=%v 命中=%d TotalMatches=%d MatchedBlocks=%d 有后续游标=%v\n\n",
		err, len(none.Hits), none.TotalMatches, none.MatchedBlocks, none.NextCursor != "")

	// 第一页固定完整高度范围：第一页之后追加的更高区块在本次翻页中既不可见，
	// 也不会帮助任何标识达标。To 留空表示取首查看到的链顶（此时为 3）。
	pinned, err := index.QueryTxs(indexroom.TxQuery{MinBlocks: 2, PageSize: 2})
	if err != nil {
		panic(err)
	}
	mustAppend(index, indexroom.Block{Height: 4, Hash: "h4", Parent: "h3", Txs: []string{"p"}})
	fmt.Printf("第一页后追加高度 4（含 p；p 原本只在高度 2 出现），当前链顶 tip=%d\n", index.Tip)
	cont := indexroom.TxQuery{MinBlocks: 2, PageSize: 2, Cursor: pinned.NextCursor}
	kept := append([]indexroom.TxHit{}, pinned.Hits...)
	statsHold := true
	for {
		page, err := index.QueryTxs(cont)
		if err != nil {
			panic(err)
		}
		kept = append(kept, page.Hits...)
		if page.TotalMatches != 5 || page.MatchedBlocks != 3 || page.ToHeight != 3 {
			statsHold = false
		}
		if page.NextCursor == "" {
			break
		}
		cont.Cursor = page.NextCursor
	}
	fmt.Print("沿用旧游标翻完：命中")
	for _, hit := range kept {
		fmt.Printf(" 高度%d/%q@%d", hit.Height, hit.TxID, hit.Position)
	}
	fmt.Printf("\n  共 %d 条，全部不超过高度 3，p 未出现；每页统计都是 5/3、ToHeight=3：%v\n", len(kept), statsHold)

	// 需要新区块参与达标判定时，从空游标重新查询：p 现在出现在区块 {2,4}，
	// 也达到门槛。
	restart, err := index.QueryTxs(indexroom.TxQuery{MinBlocks: 2})
	if err != nil {
		panic(err)
	}
	fmt.Printf("空游标重新查询（范围重新固定到链顶 4）：命中 %d 条，TotalMatches=%d MatchedBlocks=%d ToHeight=%d\n\n",
		len(restart.Hits), restart.TotalMatches, restart.MatchedBlocks, restart.ToHeight)

	fmt.Println("---- 门槛与 TxIDs 筛选、时间窗口共同生效 ----")
	// 高度 1 时间 100、高度 2 缺失时间、高度 3 时间 105，三个区块都含 k 与 r。
	win := indexroom.New()
	mustAppend(win, indexroom.Block{Height: 1, Hash: "w1", Parent: "genesis", Txs: []string{"k", "r"}, Time: unix(100)})
	mustAppend(win, indexroom.Block{Height: 2, Hash: "w2", Parent: "w1", Txs: []string{"k", "r"}})
	mustAppend(win, indexroom.Block{Height: 3, Hash: "w3", Parent: "w2", Txs: []string{"k", "r"}, Time: unix(105)})

	// 启用窗口 [100,110)：高度 2 缺失时间，不参与计数、其中的出现也不返回；
	// k 只靠窗口内的区块 {1,3} 计数，恰好达到门槛 2，保留这两次出现。
	// r 虽在三个区块都有，但不通过 TxIDs 筛选，根本不参与计数。
	enabled, err := win.QueryTxs(indexroom.TxQuery{
		TxIDs: []string{"k"}, TimeStart: unix(100), TimeEnd: unix(110), MinBlocks: 2,
	})
	if err != nil {
		panic(err)
	}
	printPage("窗口 [100,110)、筛选 k、门槛 2（缺失时间的高度2不帮忙）", enabled)

	// 窗口收窄为 [100,105)：高度 3 时间正好等于被排除的终点，窗口内只剩
	// 高度 1，没有人达到门槛——成功的空页、零统计、空游标。
	narrow, err := win.QueryTxs(indexroom.TxQuery{
		TxIDs: []string{"k"}, TimeStart: unix(100), TimeEnd: unix(105), MinBlocks: 2,
	})
	if err != nil {
		panic(err)
	}
	fmt.Printf("窗口 [100,105)（高度2缺失时间、高度3在被排除的终点）：命中=%d TotalMatches=%d MatchedBlocks=%d 有后续游标=%v\n",
		len(narrow.Hits), narrow.TotalMatches, narrow.MatchedBlocks, narrow.NextCursor != "")

	// 不启用时间窗口时，缺失时间不会仅因没有时间而被排除：三个区块都参与
	// 计数，k 达到门槛，三次出现（含高度 2）全部保留。
	off, err := win.QueryTxs(indexroom.TxQuery{TxIDs: []string{"k"}, MinBlocks: 2})
	if err != nil {
		panic(err)
	}
	fmt.Printf("不启用窗口、筛选 k、门槛 2：命中=%d TotalMatches=%d MatchedBlocks=%d（缺失时间的高度2也参与）\n",
		len(off.Hits), off.TotalMatches, off.MatchedBlocks)
}
```

