package indexroom

import (
	"fmt"
)

// MaxTimeBuckets is the largest number of segments one QueryTimeStats call
// may return.
const MaxTimeBuckets = 10000

// statsQueryHookLocked is a test-only rendezvous invoked once per
// QueryTimeStats call while index.mu is held, with the resolved tip-bound
// height (after clamping, before any block is scanned). It is nil in
// production; reorg regression tests set it to park a query that has already
// pinned its height range with the lock held, forcing a concurrent Reorg to
// wait and making the "one complete main-chain state" observation
// deterministic instead of relying on scheduling luck.
var statsQueryHookLocked func(resolvedTo int64)

// TimeStatsQuery asks for transaction statistics over a half-open time
// window, segmented into fixed-length buckets.
//
// From and To reuse the TxQuery height semantics: heights are inclusive, a
// zero From starts at height 1, a zero To pins the chain tip, and an
// explicit To above the tip is clamped to it. TxIDs reuses the exact-string
// filter semantics, including duplicates and empty identifiers.
//
// Start and End are Unix seconds bounding the window [Start, End): Start is
// included, End is excluded. Both must be non-negative and Start must be
// below End. StepSeconds is the bucket length in seconds and must be
// positive; buckets start at Start and the final bucket is cut off at End.
// Times outside any int64 range cannot be requested.
type TimeStatsQuery struct {
	From        int64
	To          int64
	TxIDs       []string
	Start       int64
	End         int64
	StepSeconds int64
}

// TimeBucket is statistics for one half-open segment [Start, End). Buckets
// with no matching transactions are returned with every count at zero.
type TimeBucket struct {
	Start int64
	End   int64
	// TxCount counts matching transaction occurrences in the segment.
	TxCount int64
	// DistinctTxIDs counts the different matching identifiers in the segment.
	DistinctTxIDs int64
	// Blocks counts blocks whose timestamp falls in the segment and which
	// hold at least one matching transaction.
	Blocks int64
}

// TimeTotals summarizes the whole window with the same counters as a bucket.
// DistinctTxIDs is deduplicated over the whole window, not summed from the
// per-bucket values.
type TimeTotals struct {
	TxCount       int64
	DistinctTxIDs int64
	Blocks        int64
}

// TimeStats is the result of QueryTimeStats. Buckets are ordered by ascending
// time and always cover the whole requested window, even on an empty chain,
// above the chain tip, or when nothing matches. MissingTimeBlocks reports how
// many blocks in the resolved height range carry no timestamp; those blocks
// never enter a bucket, and the count ignores the transaction filter.
type TimeStats struct {
	Buckets []TimeBucket
	Totals  TimeTotals
	// FromHeight and ToHeight are the resolved inclusive height bounds,
	// clamped to the chain tip observed by this call.
	FromHeight int64
	ToHeight   int64
	// MissingTimeBlocks counts blocks in [FromHeight, ToHeight] without a
	// timestamp, regardless of the transaction filter.
	MissingTimeBlocks int64
}

// QueryTimeStats buckets matching transactions by block timestamp over the
// requested height range. The call observes one complete main-chain state:
// concurrent Append, Reorg, or Restore calls never mix old and new blocks
// into the answer, and the index is never modified.
func (index *Index) QueryTimeStats(query TimeStatsQuery) (TimeStats, error) {
	from, to, err := normalizeRange(query.From, query.To)
	if err != nil {
		return TimeStats{}, err
	}
	if query.Start < 0 {
		return TimeStats{}, fmt.Errorf("%w: start time must not be negative", ErrInvalidArgument)
	}
	if query.End < 0 {
		return TimeStats{}, fmt.Errorf("%w: end time must not be negative", ErrInvalidArgument)
	}
	if query.Start >= query.End {
		return TimeStats{}, fmt.Errorf("%w: start time must be below end time", ErrInvalidArgument)
	}
	if query.StepSeconds <= 0 {
		return TimeStats{}, fmt.Errorf("%w: step seconds must be positive", ErrInvalidArgument)
	}

	// Window length is positive and bounded by MaxInt64 since End > Start.
	width := query.End - query.Start
	count := width / query.StepSeconds
	if width%query.StepSeconds != 0 {
		count++
	}
	if count > MaxTimeBuckets {
		return TimeStats{}, fmt.Errorf("%w: time window would produce %d buckets, limit is %d",
			ErrInvalidArgument, count, MaxTimeBuckets)
	}

	// One canonical filter backs the statistics scan, so matching and the
	// empty-list-vs-{""} distinction behave exactly as in QueryTxs.
	filter := newTxFilter(query.TxIDs)

	stats := TimeStats{Buckets: make([]TimeBucket, count)}
	for i := range stats.Buckets {
		stats.Buckets[i].Start = bucketBoundary(query.Start, query.StepSeconds, int64(i))
		// A saturated boundary (MaxInt64) and the overshooting final step
		// are both cut back to the requested window end.
		end := bucketBoundary(query.Start, query.StepSeconds, int64(i)+1)
		if end > query.End {
			end = query.End
		}
		stats.Buckets[i].End = end
	}

	index.mu.Lock()
	defer index.mu.Unlock()

	if to == 0 || to > index.Tip {
		to = index.Tip
	}
	stats.FromHeight = from
	stats.ToHeight = to
	if from > to {
		// Empty index or a start above the tip: zeroed buckets are still
		// returned for the whole requested window.
		return stats, nil
	}

	if statsQueryHookLocked != nil {
		statsQueryHookLocked(to)
	}

	distinct := make([]map[string]struct{}, count)
	windowDistinct := make(map[string]struct{})
	for height := from; height <= to; height++ {
		block := index.Blocks[height]
		if block.Time == nil {
			stats.MissingTimeBlocks++
			continue
		}
		t := *block.Time
		if t < query.Start || t >= query.End {
			continue
		}
		bucket := (t - query.Start) / query.StepSeconds
		matched := false
		for _, tx := range block.Txs {
			if !filter.matches(tx) {
				continue
			}
			stats.Buckets[bucket].TxCount++
			stats.Totals.TxCount++
			if distinct[bucket] == nil {
				distinct[bucket] = make(map[string]struct{})
			}
			distinct[bucket][tx] = struct{}{}
			windowDistinct[tx] = struct{}{}
			matched = true
		}
		if matched {
			stats.Buckets[bucket].Blocks++
			stats.Totals.Blocks++
		}
	}
	for i := range distinct {
		stats.Buckets[i].DistinctTxIDs = int64(len(distinct[i]))
	}
	stats.Totals.DistinctTxIDs = int64(len(windowDistinct))
	return stats, nil
}

// bucketBoundary returns Start + step*index, saturated at MaxInt64 instead
// of overflowing. Callers cut saturated and trailing boundaries back to the
// requested window end.
func bucketBoundary(start, step, index int64) int64 {
	offset := saturatingMul(step, index)
	if offset > 1<<63-1-start {
		return 1<<63 - 1
	}
	return start + offset
}

// saturatingMul multiplies non-negative a and b, saturating at MaxInt64.
func saturatingMul(a, b int64) int64 {
	if a == 0 || b == 0 {
		return 0
	}
	if a > (1<<63-1)/b {
		return 1<<63 - 1
	}
	return a * b
}

## 重组指南（Reorg）

`Index.Reorg(blocks []Block) (dropped []int64, err error)` 用提交的**分支**整体替换主链在某个已索引父区块之后的全部内容，并返回旧内容发生变化或被删除的高度（升序）。调用与查询、摄取、快照可并发，每次调用看到的都是一个完整的链状态；重组失败不会留下半截分支。

### 分支范围：父哈希必须已索引，父之后整体替换

准备 `Reorg` 输入时按下面的边界组织分支，这是最容易理解错的一点：

- **第一个新区块的父哈希（`blocks[0].Parent`）必须对应当前主链中已经索引的某个区块**。设该父区块高度为 `a`，则分支第一个区块的高度必须是 `a+1`。
- **分支内部高度连续、逐个连接**：从第二个区块起，每个区块高度必须是前一块高度加一，父哈希必须等于前一块的哈希；分支末尾区块的高度就是重组后的**新链顶**。
- **父区块及其之前的主链原样保留；父区块高度之后的内容由提交的分支整体替换**——无论主链原来在这段有多少区块，重组后这段恰好是分支里的区块。分支比旧链短时，多出的旧区块被删除，链顶随之降到分支末尾。
- 因此**不能只提交“变化的区块”然后指望旧链余下部分自动保留**：若新链顶之后还有旧区块要留下，就必须把它们（或其在新链上的对应区块）一并放进分支。要替换从高度 `a+1` 开始的一段，就提交从高度 `a+1` 到目标新链顶的完整后缀。
- **与首块摄取的区别**：空索引 `Append` 第一个区块（高度 1）时，它的 `Parent` 只是命名链起点的标识，**不需要也不可能**已索引。`Reorg` 没有这个豁免——即使分支首块高度写成 1，它的父哈希仍必须能在当前主链中找到，否则返回 `branch parent is unknown`。首块摄取允许未索引起点，**不代表**重组也能拿这个标识当父哈希去替换高度 1。想用全新内容替换整条链（含高度 1），应使用 [`Restore` 整体替换](#快照导出与恢复指南exportrestore)。

分支内哈希还需满足：哈希非空、分支内不重复；**父区块及其以下保留区间的哈希不能被分支复用**（冲突返回 `hash conflicts with a retained block`）；被替换后缀里的旧哈希则允许在分支中重新出现，甚至可以出现在与原来不同的高度。负时间、非法 UTF-8 等校验与 `Append` 一致。

### 丢弃高度（dropped）报的是什么

成功时返回的 `dropped` 是一个**按高度升序**的列表，口径是**父区块之后、旧内容发生变化或被删除的高度**：

- 旧链在 `(父高度, 旧链顶]` 内、新分支也覆盖到的高度，逐块比较该高度上的**旧区块与分支区块**（高度、哈希、父哈希、按序的交易列表、时间的有无与取值全部相同才算相同）；不同就把该高度列入。
- 旧链高出新链顶的高度（分支更短、旧区块被删除）全部列入。
- 提交的区块与旧块**完全相同**的高度不列入；重新提交当前已生效的同一条分支，返回空列表。

所以它**既不是“全部提交高度”，也不是“消失的哈希数量”**：分支里与旧块相同的高度不报；反过来，某个旧哈希即使在分支别的高度重新出现，原高度内容变了仍要报。特别注意**缺失时间与真实零秒是两种不同的区块内容**（`Time == nil` 与 `Time` 指向 0），只改这一点的高度也必须列入。

### 失败是整体拒绝，没有部分生效

整支分支在应用之前完整校验：空分支、父哈希未索引、首块高度不是父高度加一、分支高度不连续、某块父哈希不等于前一块哈希、哈希为空或分支内重复、复用保留区间哈希、负时间、非法 UTF-8 等，任何一项不过（哪怕错误出现在**最后一个区块**）都会：

- 返回非 nil 错误，并返回**空的**丢弃高度列表；
- 前面看似合法的区块**不会提前生效**：原链顶、各高度区块内容、哈希→高度对应关系全部保持原状（可用再次 `Export` 逐字节比对验证）。

本功能没有为重组错误导出专用哨兵，调用方把任何非 nil 返回当作“本次分支被整体拒绝、状态未变”处理即可，修正分支后重新提交。重组成功后，之前分页查询取得的游标仍按[既有固定范围规则](#游标失效区分-errquerychanged-与-errinvalidargument)校验：固定范围内区块变化（即使只改时间）或链顶降到固定上界以下，续查返回 `ErrQueryChanged`，此时应从空游标重新开始。

### 完整示例：缩短重组与父链接错误的整体拒绝

下面的程序只使用现有公开功能，在本机离线即可运行，源码位于 [`examples/reorg/main.go`](examples/reorg/main.go)：

```bash
go run ./examples/reorg
```

场景分四步：先准备一条高度 1 到 4 的旧链（h1/h2/h4 有时间，h3 没有时间）；再以高度 1（h1）为父提交高度 2、3 的缩短分支——高度 2 与原区块完全相同，高度 3 保持原哈希 h3、父哈希 h2 与交易列表 `[t3]`，只把时间从缺失改为 0，分支在高度 3 结束。成功后链顶为 3、高度 4 不再存在，丢弃高度按升序为 `[3,4]`：高度 2 完全相同不报，高度 3 因“缺失时间→真实零秒”而内容不同必须报，高度 4 被删除必须报。第三步用一个**全新索引**从原来的四块链重新开始（避免与成功后的状态混淆），提交同一分支但把最后一个区块（高度 3）的父哈希改错：调用返回错误、丢弃高度为 `[]`，链顶仍为 4，区块内容、哈希对应关系与再次导出文本全部保持原状。最后一步演示首块摄取的未索引起点不能用作重组父哈希。

```go
// 重组（Index.Reorg）完整示例：从一条高度 1..4 的链出发，以已索引的
// 高度 1 为父区块（分支首块高度 2，h2 与原块完全相同；h3 保持原哈希、
// 父哈希与交易列表，只把时间从缺失改为 0）做一次缩短重组；再用一个全新的
// 索引从同样的四块链出发，演示同一分支最后一个区块父链接错误时整支分支被
// 拒绝、不报告丢弃高度、原链顶/区块内容/哈希对应关系全部保持原状；最后
// 区分“首块摄取允许未索引的链起点标识”与“重组父哈希必须已索引”。
//
// 运行：go run ./examples/reorg
package main

import (
	"bytes"
	"fmt"

	"github.com/gzhysuiioo/indexroom-analytics/indexroom"
)

func mustAppend(index *indexroom.Index, block indexroom.Block) {
	if err := index.Append(block); err != nil {
		panic(err)
	}
}

// unix 返回指向给定 Unix 秒的指针，用于设置区块时间。
func unix(sec int64) *int64 { return &sec }

// timeText 把区块时间渲染成便于阅读的文本：缺失时间为 "nil（缺失）"，
// 否则为实际 Unix 秒。
func timeText(b indexroom.Block) string {
	if b.Time == nil {
		return "nil（缺失）"
	}
	return fmt.Sprintf("%d", *b.Time)
}

// heightsText 把丢弃高度列表渲染成 [3,4] 这样的文本（空列表为 []），
// 便于直接看到“按升序报告高度”，而不是 Go 默认的 [3 4]。
func heightsText(heights []int64) string {
	var sb bytes.Buffer
	sb.WriteByte('[')
	for i, h := range heights {
		if i > 0 {
			sb.WriteByte(',')
		}
		fmt.Fprint(&sb, h)
	}
	sb.WriteByte(']')
	return sb.String()
}

// dumpChain 按高度升序打印每个主链区块的完整内容（哈希、父哈希、交易、
// 时间），并给出链顶与哈希→高度对应表，用来观察操作后的主链。
func dumpChain(title string, index *indexroom.Index) {
	fmt.Println(title)
	for h := int64(1); h <= index.Tip; h++ {
		b := index.Blocks[h]
		fmt.Printf("  高度 %d：hash=%s parent=%s txs=%q 时间=%s\n",
			h, b.Hash, b.Parent, b.Txs, timeText(b))
	}
	fmt.Printf("  链顶 tip=%d；ByHash=%v\n", index.Tip, index.ByHash)
}

// exportText 返回当前主链的规范化导出文本，用于逐字节核对失败前后的链内容。
func exportText(index *indexroom.Index) string {
	var buf bytes.Buffer
	if err := index.Export(&buf); err != nil {
		panic(err)
	}
	return buf.String()
}

// newFourBlockChain 返回一条高度 1..4 的链，用于成功与失败两个场景。
// h1、h2、h4 有正常时间（链上只要有任一块带时间，再导出即为版本 2），
// h3 没有时间（这是成功重组要修改的唯一内容）。
func newFourBlockChain() *indexroom.Index {
	idx := indexroom.New()
	mustAppend(idx, indexroom.Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1"}, Time: unix(100)})
	mustAppend(idx, indexroom.Block{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t2"}, Time: unix(200)})
	mustAppend(idx, indexroom.Block{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"t3"}})
	mustAppend(idx, indexroom.Block{Height: 4, Hash: "h4", Parent: "h3", Txs: []string{"t4"}, Time: unix(400)})
	return idx
}

