// cursor invalidation.
func TestEqualBlockContent(t *testing.T) {
	base := Block{Height: 5, Hash: "h", Parent: "p", Txs: []string{"ab", "c"}, Time: nil}
	sec := func(v int64) *int64 { return &v }

	same := []struct {
		name string
		mut  func(*Block)
	}{
		{"identical", func(b *Block) {}},
		{"nil txs equals empty txs", func(b *Block) { b.Txs = []string{} }},
		{"same timestamp seconds", func(b *Block) { b.Time = sec(42) }},
	}
	for _, tc := range same {
		t.Run(tc.name, func(t *testing.T) {
			a := base
			if base.Time == nil {
				// baseline carries no time; the timestamp case sets it on both
			}
