				t.Fatalf("expected equal: %+v vs %+v", a, b)
			}
		})
	}

	diff := []struct {
		name string
		mut  func(*Block)
	}{
		{"height", func(b *Block) { b.Height++ }},
		{"hash", func(b *Block) { b.Hash = "h2" }},
		{"parent", func(b *Block) { b.Parent = "p2" }},
		{"missing time vs real zero", func(b *Block) { b.Time = sec(0) }},
		{"changed seconds", func(b *Block) { b.Time = sec(8) }},
		{"swapped identifiers", func(b *Block) { b.Txs = []string{"c", "ab"} }},
		{"re-split identifiers", func(b *Block) { b.Txs = []string{"a", "bc"} }},
		{"added duplicate", func(b *Block) { b.Txs = []string{"ab", "c", "ab"} }},
		{"removed identifier", func(b *Block) { b.Txs = []string{"ab"} }},
		{"identifier case", func(b *Block) { b.Txs = []string{"AB", "c"} }},
		{"identifier whitespace", func(b *Block) { b.Txs = []string{" ab ", "c"} }},
		{"empty identifier inserted", func(b *Block) { b.Txs = []string{"", "ab", "c"} }},
	}
	for _, tc := range diff {
		t.Run(tc.name, func(t *testing.T) {
			a := base
			b := base
			tc.mut(&b)
			if tc.name == "changed seconds" {
				a.Time = sec(7)
			}
			if equalBlockContent(a, b) {
